/* Clock helpers for the Now page.
 *
 * The whole page is scoped to "the next few hours", so what "now" is matters
 * more here than anywhere else. Once the app switches off its testing pre-set
 * and onto the device's real clock (a confirmed in-UK location does that), that
 * clock has to keep moving — these are the two bits of the ticker that are pure
 * enough to test on their own. Everything else about the tick is DOM work and
 * lives in app.js.
 */

/* Milliseconds from `date` to the very next turn of the minute.
 *
 * The ticker re-arms with this rather than a flat 60 000 ms so it fires ON the
 * minute instead of drifting a little later with every hop — the displayed
 * clock changes when the real one does. Exactly on the minute returns a whole
 * minute (the next boundary), never 0, so a timer can't spin. */
export function msToNextMinute(date) {
  const elapsed = date.getSeconds() * 1000 + date.getMilliseconds();
  return 60000 - elapsed;
}

/* Short name of a time zone at a given moment — "BST" / "GMT" for the UK. The
 * label beside the clock; `timeZone` defaults to the device's own zone.
 *
 * Returns "" if the browser won't say, so callers can keep whatever label they
 * were showing rather than blanking it. */
export function timeZoneLabel(date, timeZone) {
  try {
    const opts = { timeZoneName: "short" };
    if (timeZone) opts.timeZone = timeZone;
    const part = new Intl.DateTimeFormat("en-GB", opts)
      .formatToParts(date)
      .find((p) => p.type === "timeZoneName");
    return part ? part.value : "";
  } catch (err) {
    return "";
  }
}
/* The time wheel's arithmetic — what the "next commitment" picker is allowed to
 * offer, and where it opens. Pure functions of "minutes since midnight now", so
 * they're testable without a DOM (see js/__tests__/constraint-time.test.mjs).
 *
 * The rule the whole file serves: the wheel offers everything from now to the
 * end of the day and nothing before it. A picker that opens on a time you've
 * already missed — or one that skips the next hour because no show happens to
 * start in it — reads as broken. */

export const WHEEL_STEP = 5; // the wheel's minute granularity
export const WHEEL_MINUTES = ["00", "05", "10", "15", "20", "25", "30", "35", "40", "45", "50", "55"];

const LAST_SLOT = 23 * 60 + 55; // the last five-minute slot of the day

/* How far ahead the picker *opens*. Far enough that there's a real choice of
 * shows to aim for, near enough to still be part of the same outing. */
export const CONSTRAINT_DEFAULT_LEAD_MINUTES = 120;

/* The earliest slot the wheel offers: the next whole five minutes from now,
 * never past the last slot of the day (so a late-night now still has a wheel). */
export function earliestWheelMinutes(nowMinutes) {
  return Math.min(Math.ceil(nowMinutes / WHEEL_STEP) * WHEEL_STEP, LAST_SLOT);
}

/* The hours the wheel offers: the current hour through 23, zero-padded. */
export function wheelHours(nowMinutes) {
  const h0 = Math.floor(earliestWheelMinutes(nowMinutes) / 60);
  const hours = [];
  for (let h = h0; h <= 23; h++) hours.push(String(h).padStart(2, "0"));
  return hours;
}

/* Minutes offered for a given hour. Every hour gets the full set except the
 * current one, where the minutes already gone are dropped. */
export function minutesForHour(hh, nowMinutes) {
  const earliest = earliestWheelMinutes(nowMinutes);
  if (parseInt(hh, 10) !== Math.floor(earliest / 60)) return WHEEL_MINUTES;
  const floor = earliest % 60;
  return WHEEL_MINUTES.filter((m) => +m >= floor);
}

/* Where the wheel opens when nothing is chosen yet: now + the default lead,
 * snapped to the five-minute grid and kept inside today. */
export function defaultConstraintTime(nowMinutes) {
  const target =
    Math.round((nowMinutes + CONSTRAINT_DEFAULT_LEAD_MINUTES) / WHEEL_STEP) * WHEEL_STEP;
  const mins = Math.max(earliestWheelMinutes(nowMinutes), Math.min(target, LAST_SLOT));
  return `${String(Math.floor(mins / 60)).padStart(2, "0")}:${String(mins % 60).padStart(2, "0")}`;
}
/* A TTL cache for the JSON data files both pages download.
 *
 * The site ships no server it controls: GitHub Pages sets its own
 * `Cache-Control` and there is no way to vary it per file. So the freshness
 * policy lives here, on the client, where each file can be given the lifetime
 * its *content* actually has:
 *
 *   - the catalogue the planner searches turns over rarely and is the bulkiest
 *     blocking download, so it is held for days;
 *   - ticket availability moves hourly and is held for a day;
 *   - descriptions are effectively immutable and are held for a week.
 *
 * Payloads go into the Cache Storage API rather than localStorage, whose ~5 MB
 * ceiling the catalogue alone would breach. Cache Storage has no expiry of its
 * own, so the clock is kept beside it as a small localStorage map of
 * url -> epoch ms of the last fetch.
 *
 * Pure of any page: both index.html (js/app.js) and the planner (plan/plan.js)
 * resolve their relative data urls against the same origin, so they share one
 * cache and one stamp map, and a file fetched by either is reused by the other.
 */

export const DAY_MS = 24 * 60 * 60 * 1000;

const CACHE_NAME = "edfringe-data-v1";
const STAMPS_KEY = "edfringe.data.fetched.v1"; // url -> epoch ms of the last fetch

export async function fetchJson(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status} fetching ${url}`);
  return res.json();
}

/* When each cached URL was last fetched. A plain localStorage map — the
 * payloads live in Cache Storage, this is only the clock beside them. */
function fetchStamps() {
  try {
    const raw = JSON.parse(localStorage.getItem(STAMPS_KEY) || "{}");
    return raw && typeof raw === "object" ? raw : {};
  } catch {
    return {};
  }
}

function stampFetch(url) {
  try {
    localStorage.setItem(STAMPS_KEY, JSON.stringify({ ...fetchStamps(), [url]: Date.now() }));
  } catch {
    /* private mode / full quota — we just re-fetch next time */
  }
}

/**
 * fetchJson with a local copy kept for `ttlMs`.
 *
 * Inside the TTL the cached body is returned without touching the network.
 * Outside it — or with nothing cached — the network is asked, and the answer
 * replaces the copy. If that request fails and a stale copy exists, the stale
 * copy wins: a week-old description or yesterday's catalogue is far better than
 * an error page, and the caller has no way to draw anything without one.
 *
 * Degrades to a plain fetch wherever Cache Storage isn't available (it needs a
 * secure context, so `file://` and plain http get the uncached path).
 *
 * @param {string} url
 * @param {number} ttlMs how long a downloaded copy may be reused
 * @param {(err: unknown, url: string) => void} [onNote] optional log sink
 */
export async function cachedFetchJson(url, ttlMs, onNote) {
  const note = onNote || (() => {});
  let cache = null;
  try {
    if (typeof caches !== "undefined") cache = await caches.open(CACHE_NAME);
  } catch {
    cache = null;
  }
  if (!cache) return fetchJson(url);

  const fetchedAt = fetchStamps()[url];
  if (fetchedAt && Date.now() - fetchedAt < ttlMs) {
    const hit = await cache.match(url);
    if (hit) return hit.json();
  }

  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`HTTP ${res.status} fetching ${url}`);
    try {
      await cache.put(url, res.clone());
      stampFetch(url);
    } catch (err) {
      note(err, url);
    }
    return res.json();
  } catch (err) {
    const stale = await cache.match(url);
    if (stale) {
      note(err, url);
      return stale.json();
    }
    throw err;
  }
}

